      (Object.keys(ccount).length ? '<div class="plab-math">conteos condicionales: ' + order.filter(i => ccount[i]).map(i => `${i}=${ccount[i]}${ccount[i] < minc ? ' ✗' : ''}`).join(', ') + '</div>' : '') +
      (pats.length ? '<div class="plab-math">patrones frecuentes:\n' + pats.map(([p, c]) => `{${p.join(', ')}}: ${c}`).join('\n') + '</div>' : '');

    const note = $('#fp-note');
    note.className = 'plab-note';
    note.textContent = !ins ? 'Primer recorrido: se cuentan los ítems y se fija el orden global. El segundo recorrido inserta cada transacción ordenada.'
      : `T${ins} ordenada = [${ordered[ins - 1].join(', ')}]: comparte un prefijo de ${shared} nodo(s), cuyos contadores suben en 1, y crea ${created} nodo(s) nuevo(s). ` +
        `El árbol guarda ${nodes.length} nodos para ${raw} apariciones de ítems. ` +
        (pats.length ? `Con soporte mínimo ${minc}, ${item} participa en ${pats.length} patrón(es) frecuente(s).` : `${item} no alcanza el soporte mínimo ${minc} con las transacciones insertadas.`);
  }

  $('#fp-item').addEventListener('click', e => { const b = e.target.closest('button'); if (b) { item = b.dataset.value; render(); } });
  ['#fp-ins', '#fp-min'].forEach(id => $(id).addEventListener('input', render));
  render();
})();
</script>
