rango_g = {i: r for r, i in enumerate(orden_g)}

def contar_nodos(nodo):
    return sum(1 + contar_nodos(h) for h in nodo.children.values())

raiz_g, apariciones, nodos = FPNode(item="null"), [], []
for t in canastas:
    t_ord = sorted([i for i in t if i in rango_g], key=rango_g.get)
    insert_transaction(raiz_g, t_ord)
    apariciones.append((apariciones[-1] if apariciones else 0) + len(t_ord))
    nodos.append(contar_nodos(raiz_g))

