fig.update_layout(xaxis_title="Canastas insertadas", yaxis_title="Total acumulado", height=360)
fig.show()
print(f"{apariciones[-1]} apariciones de ítems -> {nodos[-1]} nodos ({nodos[-1] / apariciones[-1]:.0%})")
